1366:Result BinaryReaderObjdump::OnFuncType(Index index,
1367:                                       Index param_count,
1368:                                       Type* param_types,
1369:                                       Index result_count,
1370:                                       Type* result_types) {
1371:  if (!ShouldPrintDetails()) {
1372:    return Result::Ok;
1373:  }
1374:  printf(" - type[%" PRIindex "] (", index);
1375:  for (Index i = 0; i < param_count; i++) {
1376:    if (i != 0) {
1377:      printf(", ");
1378:    }
1379:    printf("%s", param_types[i].GetName().c_str());
1380:  }
1381:  printf(") -> ");
1382:  switch (result_count) {
1383:    case 0:
1384:      printf("nil");
1385:      break;
1386:    case 1:
1387:      printf("%s", result_types[0].GetName().c_str());
1388:      break;
1389:    default:
1390:      printf("(");
1391:      for (Index i = 0; i < result_count; i++) {
1392:        if (i != 0) {
1393:          printf(", ");
1394:        }
1395:        printf("%s", result_types[i].GetName().c_str());
1396:      }
1397:      printf(")");
1398:      break;
1399:  }
1400:  printf("\n");
1401:  return Result::Ok;
1402:}
